// Roman roads for the Roman map (RomanMapCanvas), from the Itiner-e dataset
// (de Soto, Pažout, Brughmans et al., Scientific Data 2025; CC BY 4.0). The bundled
// public/assets/roman-map/roads.json is generated by scripts/buildRomanRoads.ts,
// which documents the simplification and the name/date normalisation.

import { DATA_BASE } from './romanProvinces';

export type RoadType = 0 | 1; // 0 = Main Road, 1 = Secondary Road
export type RoadCertainty = 0 | 1 | 2; // Certain, Conjectured, Hypothetical

export interface RomanRoad {
  type: RoadType;
  certainty: RoadCertainty;
  /** Historical years (negative = BCE, no year 0); null = not dated in the dataset. */
  from: number | null;
  fromErr: number; // years before `from` the road may already have existed
  to: number | null;
  toErr: number; // years after `to` it may still have been in use
  segment: string; // "Caesarea Maritima-Legio": end points, ancient or modern toponyms
  viae: string[]; // Latin road names ("Via Appia")
  itineraria: string[]; // ancient itineraries listing the segment
  recentiora: string[]; // modern road names ("Watling Street"), never used as labels
  fontes: string | null; // bibliography
  conditor: string | null; // builder, Latin nomenclature
  conditorYears: [number, number] | null;
  lengthM: number;
  /** Each part as interleaved [lng, lat, lng, lat, …]. */
  parts: Float32Array[];
  lngMin: number; lngMax: number; latMin: number; latMax: number;
}

type RawRoad = [
  RoadType, RoadCertainty, number | null, number, number | null, number, number,
  number[], number[], number[], number, number, [number, number] | null, number, number[],
];

const QUANT = 1e4;

const decode = (json: { strings: string[]; roads: RawRoad[] }): RomanRoad[] => {
  const s = json.strings;
  return json.roads.map(([type, certainty, from, fromErr, to, toErr, segment, viae, itineraria,
    recentiora, fontes, conditor, conditorYears, lengthM, coords]) => {
    const parts: Float32Array[] = [];
    let lngMin = Infinity, lngMax = -Infinity, latMin = Infinity, latMax = -Infinity;
    for (let i = 0; i < coords.length;) {
      const n = coords[i++];
      const part = new Float32Array(n * 2);
      let x = 0, y = 0;
      for (let k = 0; k < n; k++) {
        x += coords[i++];
        y += coords[i++];
        const lng = x / QUANT, lat = y / QUANT;
        part[2 * k] = lng;
        part[2 * k + 1] = lat;
        if (lng < lngMin) lngMin = lng;
        if (lng > lngMax) lngMax = lng;
        if (lat < latMin) latMin = lat;
        if (lat > latMax) latMax = lat;
      }
      parts.push(part);
    }
    return {
      type, certainty, from, fromErr, to, toErr,
      segment: s[segment],
      viae: viae.map(i => s[i]),
      itineraria: itineraria.map(i => s[i]),
      recentiora: recentiora.map(i => s[i]),
      fontes: fontes >= 0 ? s[fontes] : null,
      conditor: conditor >= 0 ? s[conditor] : null,
      conditorYears,
      lengthM,
      parts,
      lngMin, lngMax, latMin, latMax,
    };
  });
};

let cache: RomanRoad[] | null = null;
let pending: Promise<RomanRoad[]> | null = null;

/** Fetches roads.json on first call (only when the roads layer is on); cached per session. */
export const loadRomanRoads = (): Promise<RomanRoad[]> => {
  if (cache) return Promise.resolve(cache);
  if (pending) return pending;
  pending = fetch(DATA_BASE + 'roads.json')
    .then(res => {
      if (!res.ok) throw new Error(`roads.json: HTTP ${res.status}`);
      return res.json();
    })
    .then(json => (cache = decode(json)))
    .finally(() => { pending = null; }); // a failed load can be retried
  return pending;
};

/** JS Date years are astronomical (year 0 = 1 BCE); the dataset uses historical years. */
export const historicalYear = (date: Date) => {
  const y = date.getFullYear();
  return y > 0 ? y : y - 1;
};

/**
 * Whether the road existed in `year`, from the dataset's own dating, with its
 * error margins taken as "may have existed": 'yes' / 'no' when the dataset dates the
 * road, 'unknown' when it gives no date at all (most segments).
 */
export const roadExistence = (road: RomanRoad, year: number): 'yes' | 'no' | 'unknown' => {
  if (road.from === null && road.to === null) return 'unknown';
  if (road.from !== null && year < road.from - road.fromErr) return 'no';
  if (road.to !== null && year > road.to + road.toErr) return 'no';
  return 'yes';
};
